import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;
  const group = new Group();
  const timelines = [];

  // 1. PALETTE TOKENS
  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  // 2. STAGE BACKDROP (Fills the scene behind, preventing FLAT_VOID)
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();

  // Custom vertical gradient from Ink to Surface with a subtle Red Accent vignette at bottom
  const backdropUv = uv();
  const baseGrad = mix(color(ink), color(surface), backdropUv.y);
  const accentGlow = color(accent).mul(backdropUv.y.oneMinus().pow(3.0).mul(0.12));
  backdropMat.colorNode = baseGrad.add(accentGlow);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 2.0, -3.0); // Keep well behind content
  group.add(backdrop);

  // 3. CTA BUTTON PLATE
  const buttonWidth = 2.4;
  const buttonHeight = 0.65;
  const plateGeo = new PlaneGeometry(buttonWidth, buttonHeight);

  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.55,
    transparent: true,
    opacity: 0.95
  });

  // Load brushed-metal mapping
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = 1000;
      plateMat.roughnessMap = tex;
      plateMat.metalnessMap = tex;
      plateMat.needsUpdate = true;
    });
  }

  // Engineered procedural border via Node Material
  const borderUv = uv();
  const edgeX = borderUv.x.sub(0.5).abs().multiply(2.0);
  const edgeY = borderUv.y.sub(0.5).abs().multiply(2.0);
  const borderMask = edgeX.max(edgeY).step(0.96); // Clean sharp edge
  plateMat.colorNode = mix(color(surface), color(accent), borderMask);

  const plate = new Mesh(plateGeo, plateMat);
  group.add(plate);

  // 4. CTA TEXT (JetBrains Mono variant style)
  // Retrieve copy securely
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const directText = textItems.find(t => t.text)?.text || "Get started";

  const labelText = ctx.fontAtlas.createText(directText, {
    fontSize: 0.16,
    color: paper,
    align: 'center',
    letterSpacingPx: 3
  });
  // Ground depth plane
  labelText.position.set(0, -0.04, 0.05);
  group.add(labelText);

  // 5. ENTRANCE WEIGHTED SETTLE
  group.scale.set(0.01, 0.01, 0.01);
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: 'power4.out'
  });
  timelines.push(tl);

  // 6. CLEANUP HANDLER
  group.userData.cleanup = function() {
    timelines.forEach(t => t.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
  };

  return group;
}
